 await host.send({type:'cast',id:finale.instance,options:{x:10,targets:['card:'+ritual.instance,'card:'+feed.instance]}});await sync();await pass();await host.send({type:'oracleChoice',keys:[ritual.instance]});await sync();await host.send({type:'cast',id:ritual.instance});await sync();await host.send({type:'oracleChoice',keys:[feed.instance]});await sync();await host.send({type:'cast',id:feed.instance,options:{targets:['card:'+target.instance]}});await sync();assert.equal(host.snapshot.game.pendingEffect.step.op,'retargetCopy');await assert.rejects(peer.send({type:'oracleChoice',keys:[]}),/choosing/);await host.send({type:'oracleChoice',keys:[]});await sync();await host.send({type:'oracleChoice',keys:[]});await sync();assert.equal(host.snapshot.game.pendingEffect.step.op,'orderCopies');third.disconnectForTest();const ids=host.snapshot.game.pendingEffect.context.copyOrder.map(ref=>ref.id).reverse();await host.send({type:'oracleChoice',keys:ids});await sync();for(const c of clients){assert.equal(c.snapshot.game.stack.at(-1).card.instance,ids[0]);assert.equal(c.snapshot.game.stack.length,6);assert.equal(c.snapshot.game.players[0].zones.battlefield.find(c=>c.instance===kess.instance).graveCastUses,undefined);}for(let i=0;i<6;i++)await pass();for(const c of clients){assert.equal(c.snapshot.game.players[0].life,37);assert.equal(c.snapshot.game.players[0].mana[0].amount,9);assert.equal(c.snapshot.game.stack.length,0);assert.equal(c.snapshot.game.pendingEffect,undefined);}
