 const records=JSON.parse(await fs.readFile(new URL('./fixtures/commander/oracle/atraxa_praetors_voice.json',import.meta.url),'utf8')).cards,seed=game(3);seed.active=1;
 const source={...structuredClone(records.find(c=>c.name==='Tekuthal, Inquiry Dominus')),instance:crypto.randomUUID(),counters:{}},donor=card('Counter donor',{type_line:'Artifact',oracle_text:''});
 seed.players[1].zones.hand.push(source,donor);transfer(seed,source.instance,'battlefield',1);transfer(seed,donor.instance,'battlefield',1);donor.counters={charge:4};seed.players[1].mana=[{type:'C',amount:1}];
 const {clients}=await setup(t,3,{seed,checkpoint:true}),[host,peer,third]=clients,sync=()=>eventually(()=>clients.every(c=>c.snapshot.revision===host.snapshot.revision));
 const action={type:'activate',id:source.instance,ability:'action:2',choice:{allowLife:true,spend:{C:1},counterPayments:[{id:donor.instance,battlefieldId:donor.battlefieldId,kind:'charge',amount:3}]}};
 await assert.rejects(host.send(action),/control/);await assert.rejects(third.send(action),/control/);
 await peer.send(action);await sync();for(const client of clients){const g=client.snapshot.game;assert.equal(g.players[1].life,36);assert.equal(g.players[1].zones.battlefield.find(c=>c.instance===donor.instance).counters.charge,1);assert.equal(g.players[1].zones.battlefield.find(c=>c.instance===source.instance).counters.indestructible,undefined);assert.equal(g.stack.length,1);}
 peer.disconnectForTest();await host.send({type:'responseMode',mode:'prompt'});await sync();assert.equal(peer.snapshot.game.players[1].life,36);
 for(const client of [peer,third,host]){await sync();await client.send({type:'pass'});}await sync();assert.ok(clients.every(c=>c.snapshot.game.players[1].zones.battlefield.find(c=>c.instance===source.instance).counters.indestructible===1));
